#include <pthread.h>
#include <stdint.h>
#include <stdio.h>
#include <unistd.h>

#define NTHREADS 4

struct job {
  int id;
  const unsigned char *data;
  size_t len;
};

static struct job jobs[NTHREADS];

static void *sum_chunk(void *arg) {
  struct job *job = arg;
  uint64_t sum = 0;
  for (size_t i = 0; i < job->len; i++) sum += job->data[i];
  printf("chunk %d: %llu\n", job->id, (unsigned long long)sum);
  return NULL;
}

void checksum(const unsigned char *data, size_t len) {
  size_t step = len / NTHREADS;
  for (int i = 0; i < NTHREADS; i++) {
    jobs[i].id = i;
    jobs[i].data = data + step * i;
    jobs[i].len = i == NTHREADS - 1 ? len - step * i : step;
    pthread_t tid;
    pthread_create(&tid, NULL, sum_chunk, &jobs[i]);
  }
  sleep(1);
}

