#include <pthread.h>
#include <stdint.h>
#include <stdlib.h>

#define NTHREADS 4

struct job {
  const unsigned char *data;
  size_t len;
};

static void *sum_chunk(void *arg) {
  const struct job *job = arg;
  uint64_t *sum = malloc(sizeof *sum);
  if (sum == NULL) return NULL;
  *sum = 0;
  for (size_t i = 0; i < job->len; i++) *sum += job->data[i];
  return sum;
}

int checksum(const unsigned char *data, size_t len, uint64_t *total) {
  struct job jobs[NTHREADS];
  size_t step = len / NTHREADS;
  *total = 0;
  for (int i = 0; i < NTHREADS; i++) {
    jobs[i].data = data + step * i;
    jobs[i].len = i == NTHREADS - 1 ? len - step * i : step;
    pthread_t tid;
    if (pthread_create(&tid, NULL, sum_chunk, &jobs[i]) != 0) return -1;
    void *ret;
    pthread_join(tid, &ret);
    if (ret == NULL) return -1;
    *total += *(uint64_t *)ret;
    free(ret);
  }
  return 0;
}

int checksum(const unsigned char *data, size_t len, uint64_t *total) {
  struct job jobs[NTHREADS];
  pthread_t tids[NTHREADS];
