  int started = 0;
  for (; started < NTHREADS; started++) {
    jobs[started].data = data + step * started;
    jobs[started].len = started == NTHREADS - 1 ? len - step * started : step;
    if (pthread_create(&tids[started], NULL, sum_chunk, &jobs[started]) != 0) break;
  }
  int rc = started == NTHREADS ? 0 : -1;
  *total = 0;
  for (int i = 0; i < started; i++) {
    void *ret;
    pthread_join(tids[i], &ret);
    if (ret == NULL) {
